package ds.seed7992;

import ds.Identifier;
import org.junit.Before;
import org.junit.Test;
import org.junit.experimental.categories.Category;

import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

/**
 * Marker interface used to tag unit tests in this file.
 */
interface UnitTest {}

/**
 * Improved, maintainable unit tests for the Identifier class.
 *
 * These tests were rewritten from autogenerated scaffolding to:
 * - use a shared setup to avoid duplication,
 * - include descriptive failure messages,
 * - follow a simple Given-When-Then structure in each test,
 * - include lightweight complementary assertions (idempotence / consistency)
 *   without assuming more about the implementation than the original tests did.
 *
 * Note: The method names are preserved exactly as required by the test harness.
 */
@Category(UnitTest.class)
public class EvoAITest extends Identifier_ESTest_scaffolding {

    private Identifier identifier;

    @Before
    public void setUp() {
        // Given: a fresh Identifier instance for each test to avoid inter-test coupling.
        identifier = new Identifier();
    }

    /**
     * Given a digit character '4'
     * When checking valid_f
     * Then the method should indicate the character is valid (per original behavior),
     * and subsequent identical calls should be consistent (idempotence).
     */
    @Test(timeout = 4000)
    public void test0() throws Throwable {
        // Given
        char ch = '4';

        // When
        boolean first = identifier.valid_f(ch);

        // Then
        assertTrue("Expected valid_f('4') to be true (digit accepted as valid first char per baseline).", first);
        // Idempotence / consistency: repeated calls produce the same result.
        assertEquals("valid_f should be deterministic for the same input character.", first, identifier.valid_f(ch));

        // Complementary sanity check derived from other tests in this suite:
        // characters known to be invalid in baseline (e.g. '{') remain invalid.
        boolean brace = identifier.valid_f('{');
        assertFalse("Expected valid_f('{') to be false (character not allowed as first char per baseline).", brace);
    }

    /**
     * Given a punctuation character '{'
     * When checking valid_f
     * Then the method should indicate the character is invalid and be deterministic.
     */
    @Test(timeout = 4000)
    public void test1() throws Throwable {
        // Given
        char ch = '{';

        // When
        boolean result = identifier.valid_f(ch);

        // Then
        assertFalse("Expected valid_f('{') to be false (punctuation disallowed as first char).", result);
        // Determinism check
        assertEquals("valid_f should return the same result when called multiple times with the same input.", result, identifier.valid_f(ch));

        // Extra consistency: ensure that a known valid character ('4') is not reported the same as '{'.
        boolean digit = identifier.valid_f('4');
        assertNotEquals("Different character classes should not necessarily yield identical validity.", result, digit);
    }

    /**
     * Given a punctuation character '}'
     * When checking valid_s (valid as a subsequent character)
     * Then the method should indicate the character is invalid and be deterministic.
     */
    @Test(timeout = 4000)
    public void test2() throws Throwable {
        // Given
        char ch = '}';

        // When
        boolean result = identifier.valid_s(ch);

        // Then
        assertFalse("Expected valid_s('}') to be false (punctuation not allowed as subsequent char).", result);
        // Determinism
        assertEquals("valid_s should be deterministic for the same input.", result, identifier.valid_s(ch));

        // Complementary check using a baseline-valid subsequent character ('r').
        boolean letter = identifier.valid_s('r');
        assertTrue("Expected valid_s('r') to be true (letters are allowed as subsequent characters per baseline).", letter);
    }

    /**
     * Given a lowercase letter 'r'
     * When checking valid_s
     * Then the method should indicate the character is valid and be repeatable.
     */
    @Test(timeout = 4000)
    public void test3() throws Throwable {
        // Given
        char ch = 'r';

        // When
        boolean first = identifier.valid_s(ch);

        // Then
        assertTrue("Expected valid_s('r') to be true (letters allowed as subsequent chars).", first);
        // Repeatability check
        assertEquals("Subsequent calls to valid_s with same char should be consistent.", first, identifier.valid_s(ch));

        // Sanity: ensure a known invalid subsequent char remains invalid.
        assertFalse("Expected valid_s('}') to remain false as a complementary sanity check.", identifier.valid_s('}'));
    }

    /**
     * Given the multi-letter string "ZHkFQY" (baseline failed case)
     * When validating the identifier
     * Then the method should indicate it is invalid per the original baseline,
     * and similar short identifiers may be valid (sanity check).
     */
    @Test(timeout = 4000)
    public void test4() throws Throwable {
        // Given
        String s = "ZHkFQY";

        // When
        boolean result = identifier.validateIdentifier(s);

        // Then
        assertFalse("Expected validateIdentifier(\"ZHkFQY\") to be false per baseline behavior.", result);
        // Determinism
        assertEquals("validateIdentifier should be deterministic for the same input string.", result, identifier.validateIdentifier(s));

        // Sanity: single-letter identifier known to be valid in baseline.
        assertTrue("Expected validateIdentifier(\"M\") to be true (single-letter identifier accepted per baseline).", identifier.validateIdentifier("M"));
    }

    /**
     * Given the single-character string "M"
     * When validating the identifier
     * Then the method should indicate it is valid and be deterministic.
     */
    @Test(timeout = 4000)
    public void test5() throws Throwable {
        // Given
        String s = "M";

        // When
        boolean first = identifier.validateIdentifier(s);

        // Then
        assertTrue("Expected validateIdentifier(\"M\") to be true (single-letter identifier accepted).", first);
        // Determinism check
        assertEquals("validateIdentifier should return the same result on repeated calls with the same input.", first, identifier.validateIdentifier(s));

        // Complementary sanity: null input is known to be invalid in baseline.
        assertFalse("Expected validateIdentifier(null) to be false (null input handled as invalid).", identifier.validateIdentifier(null));
    }

    /**
     * Given a string with spaces and special characters " tDzh*t-"
     * When validating the identifier
     * Then the method should indicate it is invalid and be repeatable.
     */
    @Test(timeout = 4000)
    public void test6() throws Throwable {
        // Given
        String s = " tDzh*t-";

        // When
        boolean result = identifier.validateIdentifier(s);

        // Then
        assertFalse("Expected validateIdentifier(\" tDzh*t-\") to be false (contains spaces/special chars).", result);
        // Determinism
        assertEquals("validateIdentifier should be deterministic for the same input.", result, identifier.validateIdentifier(s));

        // Sanity: trimmed or cleaned variants may differ; ensure baseline single-letter remains valid.
        assertTrue("Sanity check: validateIdentifier(\"M\") should still be true.", identifier.validateIdentifier("M"));
    }

    /**
     * Given a null input
     * When validating the identifier
     * Then the method should indicate null is not a valid identifier and be deterministic.
     */
    @Test(timeout = 4000)
    public void test7() throws Throwable {
        // Given
        String s = null;

        // When
        boolean result = identifier.validateIdentifier(s);

        // Then
        assertFalse("Expected validateIdentifier(null) to be false (null is not a valid identifier).", result);
        // Determinism
        assertEquals("validateIdentifier should be deterministic when called repeatedly with null.", result, identifier.validateIdentifier(s));

        // Complementary check: short valid identifier should remain valid.
        assertTrue("Sanity check: validateIdentifier(\"M\") should be true.", identifier.validateIdentifier("M"));
    }
}